#!/usr/bin/env python3
"""Build crawlable learning pages without a browser, engine or runtime package."""
import argparse
import json
import os
from pathlib import Path
import re

from public_content import COURSES, GUIDES
from public_site import SITE, NAME, PUBLIC_PATHS, esc, head, header, footer, crumbs, scripts, preview_board, account_banner

ROOT = Path(__file__).resolve().parents[2]
DEFAULT_OUT = ROOT / 'chess-dashboard/public'


def read_courses(out):
    return json.loads((out / 'app/opening-courses.js').read_text().split('window.OpeningCourses = ', 1)[1].rstrip(';\n'))


def document(title, description, path, content, *, section='', opening=None, schema=None, noindex=False):
    if path.startswith('/learn/') and path != '/learn/':
        content += account_banner()
    attr = f' data-initial-preview="{opening}"' if opening else ''
    return f'<!doctype html>\n<html lang="en">{head(title, description, path, extra_schema=schema, preview=bool(opening), noindex=noindex)}<body{attr}>{header(section)}<main id="main">{content}</main>{footer()}{scripts(bool(opening))}</body></html>\n'


def course_page(info, course):
    path = '/learn/' + info['slug'] + '/'
    breadcrumb, schema = crumbs([('Courses', '/learn/'), (info['name'], path)])
    chapters = ''.join(f'''<li><a href="/app/?opening={info['opening']}&amp;chapter={ch['id']}#today"><span class="chapter-index">{i:02}</span><span><h3>{esc(ch['title'])}</h3><p>{esc(ch['subtitle'])}</p></span><span class="chapter-size">{len(ch['cards'])} positions →</span></a></li>''' for i, ch in enumerate(course['chapters'], 1))
    outcomes = ''.join(f'<li>{esc(text)}</li>' for text in info['outcomes'])
    faqs = ''.join(f'<details><summary>{esc(q)}</summary><p>{esc(a)}</p></details>' for q, a in info['faq'])
    guide = next(g for g in GUIDES if g['slug'] == info['guide'])
    content = f'''<div class="shell">{breadcrumb}</div><section class="course-hero shell"><div class="course-hero-copy"><span class="eyebrow">GUIDED OPENING COURSE · PLAY AS {info['side'].upper()}</span><h1>Learn the <br /><em>{esc(info['name'])}.</em></h1><p class="course-tagline">{esc(info['tagline'])}</p><p class="hero-lead">{esc(info['intro'])}</p><div class="hero-actions"><a class="button primary" href="#try">Try a free lesson ↓</a><a class="quiet-link" href="#curriculum">See the chapters</a></div><p class="hero-note">No account. No game import. Just your next move.</p><p class="opening-notation">{esc(info['moves'])}</p></div>{preview_board(info['opening'])}</section>
<div class="course-facts shell"><div><strong>{len(course['chapters'])}</strong><span>guided chapters</span></div><div><strong>{len(course['cards'])}</strong><span>training positions</span></div><div><strong>Learn · Recall · Play</strong><span>ideas, memory and practical decisions</span></div></div>
<section class="cream course-details"><div class="shell curriculum-layout"><div><span class="eyebrow">THE PLAN BEHIND THE MOVES</span><h2>Know what<br />you’re playing for.</h2><p>{esc(info['audience'])}</p><ul class="learning-outcomes">{outcomes}</ul><a class="inline-link" href="/guides/{guide['slug']}/">Read: {esc(guide['title'])} →</a></div><div id="curriculum"><span class="eyebrow">YOUR COURSE</span><ol class="public-chapters">{chapters}</ol><p class="course-scope">These are authored lessons, not exhaustive opening coverage. Browse every chapter freely; your saved place resumes when you return.</p></div></div></section>
<section class="shell course-method"><div><span class="eyebrow">A LITTLE AT A TIME</span><h2>See it.<br />Remember it.<br /><em>Put it to work.</em></h2></div><ol class="practice-steps"><li><span>01</span><div><h3>Understand the position</h3><p>Board arrows, marked squares and a short explanation show what the move does.</p></div></li><li><span>02</span><div><h3>Find it without help</h3><p>Scheduled recall keeps first-attempt answers separate from hints and retries.</p></div></li><li><span>03</span><div><h3>Play beyond the line</h3><p>Try five learner moves against Stockfish from a position you have studied.</p></div></li></ol></section>
<section class="cream"><div class="shell course-faq"><div><span class="eyebrow">BEFORE YOUR FIRST MOVE</span><h2>A few good questions.</h2></div><div>{faqs}</div></div></section>
<section class="closing shell"><div><span class="eyebrow">MAKE THE FIRST MOVE</span><h2>A plan you can<br /><em>take to the board.</em></h2><a class="button primary" href="/app/?opening={info['opening']}&amp;chapter=essentials#today">Start the first chapter →</a><p>Guest progress stays on this device when storage is available.</p></div><span class="coach-art closing-coach" data-coach="maya" aria-hidden="true"></span></section>'''
    if info['opening'] == 'italian':
        content += '<section class="shell public-plan-link"><span class="eyebrow">AFTER THE OPENING MOVES</span><h2>What if they change the plan?</h2><p>Try three Italian situations and a fresh-position challenge. Get your king safe, support the centre and respond to a new threat.</p><a class="button primary" href="/app/?plan=italian#today">Practise the Italian plan →</a></section>'
    course_schema = {'@type':'Course','@id':SITE+path+'#course','name':info['name']+' opening course','description':info['intro'],'url':SITE+path,'provider':{'@id':SITE+'/#organization'},'isAccessibleForFree':True,'inLanguage':'en-GB','coursePrerequisites':'Know how the chess pieces move.'}
    return document({'italian':'Italian Game course: learn the plans | Opening Leak Lab','caro':'Learn the Caro–Kann Defence | Opening Leak Lab','queens':'Queen’s Gambit Declined course | Opening Leak Lab'}[info['opening']], info['description'], path, content, section='/learn/', opening=info['opening'], schema=[schema, course_schema])


def guide_rows():
    return ''.join(f'''<article class="reading-row"><span class="reading-number">0{i}</span><div><span class="eyebrow">{esc(g['label'])} · {g['minutes']} MIN READ</span><h3><a href="/guides/{g['slug']}/">{esc(g['title'])}</a></h3><p>{esc(g['lead'])}</p></div><a class="reading-arrow" href="/guides/{g['slug']}/" aria-label="Read {esc(g['title'])}">→</a></article>''' for i, g in enumerate(GUIDES, 1))


def guide_page(guide):
    path = '/guides/' + guide['slug'] + '/'
    breadcrumb, schema = crumbs([('Opening guides', '/guides/'), (guide['label'], path)])
    info = next(c for c in COURSES if c['opening'] == guide['opening'])
    toc = ''.join(f'<li><a href="#{key}">{esc(title)}</a></li>' for key, title, _ in guide['sections'])
    sections = ''
    for i, (key, title, text) in enumerate(guide['sections']):
        sections += f'<section id="{key}"><h2>{esc(title)}</h2>{text}</section>'
        if i == 1:
            diagram = guide['diagram']
            sections += f'<figure class="annotated-position"><img src="/assets/positions/{guide["slug"]}.svg" width="640" height="640" loading="lazy" decoding="async" alt="{esc(diagram["caption"])}" /><figcaption>{esc(diagram["caption"])}</figcaption></figure>'
    related = ''.join(f'<li><a href="/guides/{g["slug"]}/">{esc(g["title"])} →</a></li>' for g in GUIDES if g != guide)
    content = f'''<div class="shell">{breadcrumb}</div><header class="guide-heading shell"><span class="eyebrow">{esc(guide['label'])} · {guide['minutes']} MIN READ</span><h1>{esc(guide['title'])}</h1><p>{esc(guide['lead'])}</p><div class="article-byline">Opening Leak Lab · Learning notes <span>Updated <time datetime="2026-10-17">17 October 2026</time></span><a href="/about/#sources">How we check our content →</a></div></header>
<div class="shell article-layout"><aside class="article-contents"><nav aria-label="In this guide"><span class="eyebrow">IN THIS GUIDE</span><ol>{toc}</ol><a class="inline-link" href="#try">Try the board exercise ↓</a></nav></aside><article class="guide-prose">{sections}<section class="guide-related"><h2>Keep learning</h2><ul><li><a href="/learn/{info['slug']}/">Explore the {esc(info['name'])} course →</a></li>{related}</ul><p class="article-source">The chess positions and legal moves are checked with python-chess. These are practical learning notes, not a claim that one repertoire is objectively best. <a href="/about/#sources">Read our sources and method</a>.</p></section></article></div>
<section class="exercise-section shell"><div><span class="eyebrow">YOUR TURN</span><h2>Read the idea.<br /><em>Now play it.</em></h2><p>Try this position without an account. A hint is here if you need one; this public example does not write a recall result.</p><a class="inline-link" href="/learn/{info['slug']}/">See the full course →</a></div>{preview_board(guide['opening'])}</section>'''
    article = {'@type':'Article','headline':guide['title'],'description':guide['description'],'mainEntityOfPage':SITE+path,'url':SITE+path,'author':{'@id':SITE+'/#organization'},'publisher':{'@id':SITE+'/#organization'},'datePublished':'2026-10-17','dateModified':'2026-10-17','image':SITE+'/assets/brand/social.png','inLanguage':'en-GB'}
    return document({'italian-game-for-beginners':'Italian Game for beginners: moves & plans | Opening Leak Lab','caro-kann-plans':'Caro–Kann plans explained | Opening Leak Lab','remember-chess-openings':'How to remember chess openings | Opening Leak Lab'}[guide['slug']], guide['description'], path, content, section='/guides/', opening=guide['opening'], schema=[schema, article])


TRUST = {
    'about': ('About Opening Leak Lab & our chess content sources', 'An independent chess learning project. Learn how our courses, opening statistics, visual diagrams and Stockfish explanations are made and checked.', '''<p class="doc-lead">A chess repertoire should be something you understand, remember and use.</p><section><h2>An independent learning project</h2><p>Opening Leak Lab is developed by <a href="https://github.com/AdLgames">AdLgames</a>. It combines guided opening lessons, a move explorer, saved repertoires, scheduled recall and optional analysis of your own games. You can start with a board lesson before creating an account.</p><p>We focus on players who know the rules and want a clearer opening plan. Three authored courses cover the Italian Game for White, the Caro–Kann and the Queen’s Gambit Declined for Black. Reference opening guides and database statistics cover a broader set of positions; they are not all full training courses.</p></section><section id="sources"><h2>Where the chess content comes from</h2><p><strong>Course explanations:</strong> fixed, authored learning notes attached to specific positions. Legal moves, course lines and teaching-diagram attacks are checked with <a href="https://python-chess.readthedocs.io/">python-chess</a>. Automated legality checks do not establish that an explanation is the only good plan.</p><p>Static teaching boards are rendered with python-chess and use piece artwork by <a href="https://en.wikipedia.org/wiki/User:Cburnett">Colin M. L. Burnett</a>, as distributed through python-chess under GPL-3.0-or-later. <a href="/assets/positions/README.md">Attribution and source</a> · <a href="/assets/positions/COPYING.txt">Licence</a>. The live interactive board uses this project’s original piece art.</p><p><strong>Opening statistics:</strong> a book derived from public <a href="https://database.lichess.org/">Lichess game data</a> (CC0). Database pages show sample counts, the side whose score is measured, and selection thresholds. A score includes half a point for a draw. Observed results are not engine evaluations or proof of a move’s quality.</p><p><strong>Computer analysis:</strong> <a href="https://stockfishchess.org/">Stockfish</a>, distributed under GPLv3. Concrete engine output depends on search limits and is labelled separately from authored lessons. The repository includes the installer and licence information.</p><p><strong>Illustrated guides:</strong> Maya, Theo and Inez are fictional characters with fixed, authored reactions. They are not human coaches, titled players or a live advice service. Their artwork was generated for this project; asset provenance is recorded in the repository.</p></section><section><h2>What progress means here</h2><p>Introducing a position, recalling a move without help and playing a practical continuation are separate records. Hints and retries are useful practice, but do not count as first-attempt independent recall. We do not translate these records into an invented rating gain or an all-purpose mastery percentage.</p></section><section><h2>Corrections and source code</h2><p>Found a confusing explanation or a wrong position? <a href="/contact/">Report the exact page and move</a>. The <a href="https://github.com/AdLgames/chess-opening-leak-analyzer">project repository</a> contains the source, tests, dataset notes and licence details. Opening Leak Lab is independent of Chess.com, Lichess and the Stockfish project.</p></section>'''),
    'contact': ('Contact Opening Leak Lab | Feedback & chess corrections', 'Report a chess-content correction, a website bug or a feature suggestion through the Opening Leak Lab project. Find account export and deletion controls.', '''<p class="doc-lead">Something unclear? A move that needs another look? Tell us where you found it.</p><section><h2>Report a problem or suggest an improvement</h2><p>Use the project’s <a href="https://github.com/AdLgames/chess-opening-leak-analyzer/issues">GitHub issues</a> for website bugs, feature suggestions and chess-content corrections. A GitHub account is needed to post. Include the page URL, the move or position, what happened, and what you expected.</p><p><a class="button primary" href="https://github.com/AdLgames/chess-opening-leak-analyzer/issues/new">Open a project issue →</a></p><p>Issues are public. Do not include private PGNs, email sign-in links, access tokens, account exports or other personal data. For an account-access problem, describe the general issue and request a private follow-up channel before sharing identifying details.</p></section><section><h2>Account data</h2><p>You can download your saved account data or delete your account from the account menu in <a href="/app/">your workspace</a>. Signing out and deleting an account are different actions. Read <a href="/privacy/">Privacy &amp; your data</a> for what is stored locally and on the hosted service.</p></section><section><h2>Chess feedback</h2><p>For a content correction, include the guide or course name, move number and the position if possible. Explain whether the problem concerns legality, a missing alternative, an engine continuation or an unclear plan. This helps us reproduce the decision instead of guessing from a game result.</p></section>'''),
    'privacy': ('Privacy & your data | Opening Leak Lab', 'How Opening Leak Lab handles guest progress, account data, game analysis, essential sign-in storage and optional usage measurement. Export or delete your data.', '''<p class="doc-lead">Start with a lesson. Keep control of what you save.</p><p>Last updated: 17 October 2026. This page describes the hosted website at chessleaklab.co.uk, an independent project maintained by <a href="https://github.com/AdLgames">AdLgames</a>. For product and data questions, see <a href="/contact/">Contact</a>.</p><section><h2>Browsing and guest learning</h2><p>Public course previews run in your browser and do not submit game analysis or create a learning attempt. Guest repertoire entries, learning checkpoints, recall history, the most recent report and preferences are stored in browser storage when available. Someone using the same browser profile may be able to see that working copy. If storage is blocked, the app explains that progress may last only in the current tab.</p></section><section><h2>Accounts and essential storage</h2><p>Signing in uses an essential session cookie. The server stores a hash of the random session token, not the token itself. Email sign-in stores the email address; Lichess sign-in stores the provider identity and username. The Lichess sign-in access token is used to identify the account and is not retained by the current sign-in flow.</p><p>When signed in, the service stores account progress, repertoire choices, preferences, learning events, analysis history and the most recent report in the deployment’s database. Game identifiers and decision evidence allow analysis to accumulate without counting the same game twice. These records remain until you delete the account or the associated saved material.</p></section><section><h2>When you ask for game analysis</h2><p>The hosted server fetches the public Chess.com or Lichess archive you request, or receives the PGN you upload, and analyses it on the server. Archive content is processed in temporary storage, which may remain until the server instance is recycled. Saved reports and evidence are separate from those temporary archives. Do not upload games or notes you do not want processed by the hosted service.</p><p>Chess.com or Lichess receives the requested archive lookup. The hosting provider handles normal web requests and may retain operational logs, including network information, under its own policies. Email sign-in, when enabled, uses the configured transactional-email provider. The app’s source is available if you prefer to run analysis locally.</p></section><section id="measurement"><h2>Optional usage counts</h2><p id="measurementDescription">Optional usage measurement is off unless the site operator enables a provider and you choose to allow it. Learning works without it.</p><p>When enabled and allowed, counts cover page views, public lesson starts and completions, course openings and completed training sessions. They contain a fixed public page path and coarse course or session labels. They do not include chess usernames, query strings, game moves, FENs, emails, account IDs or a stored analytics identifier. The analytics provider still receives network information needed to process the request.</p><div id="measurementControls" hidden><button class="button primary" data-measurement="allow">Allow optional usage counts</button><button class="button outline" data-measurement="deny">Keep usage counts off</button><p id="measurementStatus" role="status"></p></div><p>Global Privacy Control and Do Not Track keep optional measurement off. If browser storage is unavailable, the preference lasts only for this page. You can change your choice here. The optional provider is Plausible; read its <a href="https://plausible.io/data-policy">data policy</a>.</p></section><section><h2>Download, delete and sign out</h2><p>Use <strong>Download my data</strong> in the workspace account menu to export saved account information as JSON. <strong>Delete my account</strong> removes the account and its associated database records. Browser downloads and exports you made yourself are outside that deletion. Hosting or delivery logs follow their provider’s retention policies.</p><p>Signing out clears the app’s local account working copy, but does not delete the server account. Browser site-data controls can remove guest storage. Keep a repertoire export before clearing local-only work you want to retain.</p></section>'''),
}


def build(out):
    courses = read_courses(out)
    public_courses = [{'opening':c['opening'],'side':c['side'],'chapters':len(c['chapters']),'positions':len(c['cards'])} for c in courses]
    (out/'public-courses.js').write_text('window.PublicCourses = '+json.dumps(public_courses, separators=(',', ':'))+';\n')
    domain = os.environ.get('LEAKLAB_ANALYTICS_DOMAIN', '').strip()
    if domain and domain != 'chessleaklab.co.uk':
        raise ValueError('LEAKLAB_ANALYTICS_DOMAIN must be chessleaklab.co.uk or empty.')
    (out/'site-config.js').write_text('/* Build-time public settings. No credentials belong here. */\nwindow.LeakSiteConfig = '+json.dumps({'analyticsDomain':domain})+';\n')
    pages = {}
    for info in COURSES:
        course = next(c for c in courses if c['opening'] == info['opening'])
        pages['/learn/'+info['slug']+'/'] = course_page(info, course)
    for guide in GUIDES:
        pages['/guides/'+guide['slug']+'/'] = guide_page(guide)
    breadcrumb, schema = crumbs([('Opening guides', '/guides/')])
    pages['/guides/'] = document('Chess opening guides: learn the plans behind the moves', 'Beginner-friendly chess opening guides with annotated boards, practical plans and free exercises. Learn the Italian, Caro–Kann and how to remember your repertoire.', '/guides/', f'<div class="shell">{breadcrumb}</div><section class="page-intro shell"><span class="eyebrow">THE REASON BEHIND THE MOVE</span><h1>Less memorising.<br /><em>More understanding.</em></h1><p>Opening plans, honest explanations and a board to try them on. Start with one useful idea.</p></section><section class="cream"><div class="shell reading-list">{guide_rows()}</div></section><section class="closing shell"><div><h2>Ready to play an idea?</h2><a class="button primary" href="/learn/">Find a free course →</a></div></section>', section='/guides/', schema=[schema])
    for slug, (title, description, text) in TRUST.items():
        breadcrumb, schema = crumbs([(slug.capitalize(), '/'+slug+'/')])
        pages['/'+slug+'/'] = document(title, description, '/'+slug+'/', f'<div class="shell">{breadcrumb}</div><article class="trust-page shell"><span class="eyebrow">OPENING LEAK LAB</span><h1>{"About &amp; sources" if slug=="about" else "Privacy &amp; your data" if slug=="privacy" else "Let’s make it better."}</h1>{text}</article>', schema=[schema])
    pages['/404.html'] = document('Page not found | Opening Leak Lab', 'This page could not be found. Find a chess course, an opening guide or your saved workspace.', '/404.html', '<section class="page-intro shell"><span class="eyebrow">A SMALL WRONG TURN</span><h1>This line ends here.<br /><em>Your next one doesn’t.</em></h1><p>We couldn’t find that page. Your saved learning is still in your workspace.</p><div class="hero-actions"><a class="button primary" href="/learn/">Find a course →</a><a class="quiet-link" href="/app/">Open your workspace</a></div></section>', noindex=True)
    for path, markup in pages.items():
        target = out/path.strip('/') if path.endswith('.html') else out/path.strip('/')/'index.html'
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(markup)
    # Keep the three existing, hand-authored layouts; share their SEO and shell.
    existing = [('/', 'Chess opening plans & practice | Opening Leak Lab', 'Learn chess openings and practise what comes next. Try a free Italian decision session, visual lessons and spaced practice. No account or game import needed.'), ('/learn/', 'Free chess opening courses for White & Black | Opening Leak Lab', 'Choose an Italian Game, Caro–Kann or Queen’s Gambit Declined course. Learn plans on the board, practise recall and play against Stockfish. No import needed.'), ('/coaches/', 'Meet Maya, Theo & Inez: your illustrated chess study guides', 'Choose a fictional illustrated chess study guide: Maya, Theo or Inez. Friendly board-side explanations and reactions accompany the same checked opening lessons.')]
    for path, title, description in existing:
        target = out/path.strip('/')/'index.html'
        markup = target.read_text()
        markup = re.sub(r'<head>.*?</head>', lambda _: head(title, description, path, preview=True), markup, flags=re.S)
        markup = re.sub(r'<a class="skip".*?</header>', lambda _: header(path), markup, count=1, flags=re.S)
        markup = re.sub(r'<footer class="site-foot.*?</footer>', lambda _: footer(), markup, count=1, flags=re.S)
        markup = re.sub(r'\s*<script src="/(?:app/store|app/board|app/opening-courses|public-courses|lesson-previews|companion|landing)\.js"></script>', '', markup)
        markup = re.sub(r'\s*<script defer src="/(?:app/store|app/board|app/opening-courses|public-courses|lesson-previews|companion|landing)\.js"></script>', '', markup)
        markup = markup.replace('</body>', scripts(True)+'</body>')
        target.write_text(markup)
    return pages


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--out', type=Path, default=DEFAULT_OUT)
    args = parser.parse_args()
    pages = build(args.out)
    print(f'{len(pages)} public course, guide, trust and recovery pages built; {len(PUBLIC_PATHS)} public sitemap destinations.')
